<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import CoSwitch from '../../components/ui/CoSwitch.vue';import CoSelect from '../../components/ui/CoSelect.vue';import CoTextField from '../../components/ui/CoTextField.vue';import CoButton from '../../components/ui/CoButton.vue';
import {settingsContributions,validateSetting,type SettingField} from '../../services/settings-registry';import type {SettingsCategory} from '../../services/settings-categories';import {useSettingsText} from '../../services/settings-categories';
const props=defineProps<{category:SettingsCategory}>();const st=useSettingsText();const values=ref<Record<string,unknown>>({});const errors=ref<Record<string,string>>({});const busy=ref<Record<string,boolean>>({});
const entries=computed(()=>[...settingsContributions.entries()].filter(([,v])=>v.section.category===props.category).sort((a,b)=>(a[1].section.order??0)-(b[1].section.order??0)||a[1].owner.id.localeCompare(b[1].owner.id)||a[0].localeCompare(b[0])));
let generation=0;
watch(entries,async list=>{const current=++generation;for(const [key,record]of list){const{owner,section}=record;for(const field of section.fields){const id=key+':'+field.id;try{const value=await owner.read(section.id+'.'+field.id);if(current===generation&&settingsContributions.get(key)===record)values.value[id]=value??field.default;}catch{if(current===generation)errors.value[id]=st.value('failed');}}}},{immediate:true});
async function save(key:string,field:SettingField,value:unknown){const entry=settingsContributions.get(key);if(!entry)return;const id=key+':'+field.id;busy.value[id]=true;errors.value[id]='';try{const candidate=field.type==='number'?Number(value):value;validateSetting(field,candidate);await entry.owner.write(entry.section.id+'.'+field.id,candidate);values.value[id]=candidate;}catch{errors.value[id]=st.value('failed');}finally{busy.value[id]=false;}}
</script>
<template><section v-for="[key,entry] in entries" :key="key" class="contribution"><h2>{{entry.owner.t(entry.section.titleKey)}}</h2><div v-for="field in entry.section.fields" :key="field.id" class="field"><label>{{entry.owner.t(field.titleKey)}}</label><CoSwitch v-if="field.type==='boolean'" :model-value="Boolean(values[key+':'+field.id])" :disabled="busy[key+':'+field.id]" @update:model-value="save(key,field,$event)"/><CoSelect v-else-if="field.type==='enum'" :model-value="String(values[key+':'+field.id]??field.default)" :options="(field.options??[]).map(o=>({value:o.value,label:entry.owner.t(o.titleKey)}))" @update:model-value="save(key,field,$event)"/><template v-else><CoTextField :model-value="String(values[key+':'+field.id]??field.default)" @update:model-value="values[key+':'+field.id]=$event"/><CoButton :disabled="busy[key+':'+field.id]" @click="save(key,field,values[key+':'+field.id])">{{st('save')}}</CoButton></template><span v-if="errors[key+':'+field.id]" role="alert">{{errors[key+':'+field.id]}}</span></div></section></template>
<style scoped>.contribution{margin-top:var(--copper-space-5);padding:var(--copper-space-5);background:var(--copper-surface);box-shadow:var(--copper-shadow-card);border-radius:var(--copper-radius-card)}.field{display:flex;align-items:center;gap:var(--copper-space-3);flex-wrap:wrap;padding:var(--copper-space-3) 0}.field label{flex:1;min-width:150px}.field span{color:var(--copper-danger)}</style>
